SchServer.ProcessControl.PreProcess(SchDoc, '');
Try
  NetLabel := SchServer.SchObjectFactory(eNetLabel, eCreate_Default);
  NetLabel.Text := 'CLK';
  NetLabel.Location := Point(MilsToCoord(1000), MilsToCoord(2000));
  SchDoc.RegisterSchObjectInContainer(NetLabel);
Finally
  SchServer.ProcessControl.PostProcess(SchDoc, '');
End;
SchDoc.GraphicallyInvalidate;

SchServer.RobotManager.SendMessage(Cmp.I_ObjectAddress, c_BroadCast, SCHM_BeginModify, c_NoEventData);
Cmp.Comment.Text := '4.7k';
SchServer.RobotManager.SendMessage(Cmp.I_ObjectAddress, c_BroadCast, SCHM_EndModify, c_NoEventData);

Prj := GetWorkspace.DM_FocusedProject;
For i := 0 To Prj.DM_LogicalDocumentCount - 1 Do Begin
  Doc := Prj.DM_LogicalDocuments(i);
  If Doc.DM_DocumentKind = 'SCH' Then Begin
    SchDoc := SchServer.GetSchDocumentByPath(Doc.DM_FullPath);
    If SchDoc = Nil Then SchDoc := SchServer.LoadSchDocumentByPath(Doc.DM_FullPath);
    ... process SchDoc ...
  End;
End;

Port := SchServer.SchObjectFactory(ePort, eCreate_Default);
Port.Name := 'VOUT';
Port.IOType := ePortIOOutput;
Port.Style := ePortRight;
Port.Location := Point(MilsToCoord(3000), MilsToCoord(1500));
SchDoc.RegisterSchObjectInContainer(Port);

SchDoc.PlaceSchComponent('C:\Libs\Passives.SchLib', 'RES', Handle);
Cmp := SchServer.GetCurrentSchDocument.CurrentSchComponent;  // or cast Handle
Cmp.Designator.Text := 'R1';
Cmp.Location := Point(MilsToCoord(2000), MilsToCoord(2000));

If Not SchDoc.ChooseLocationInteractively(Loc, 'Pick the top-left of the resistor ladder') Then Exit;
For i := 0 To 7 Do Begin
  SchDoc.PlaceSchComponent(LibPath, 'RES', H);
  R := SchServer.GetCurrentSchDocument.CurrentSchComponent;
  R.Location := Point(Loc.X, Loc.Y - i * MilsToCoord(400));
End;

SchServer.ProcessControl.PreProcess(SchDoc, '');
SchDoc.SheetStyle := eSheetA3;
SchDoc.WorkspaceOrientation := eLandscape;
SchDoc.VisibleGridSize := MilsToCoord(100);
SchDoc.UpdateDocumentProperties;
SchServer.ProcessControl.PostProcess(SchDoc, '');
SchDoc.GraphicallyInvalidate;

SchDoc.LockViewUpdate;
Try
  For i := 0 To 199 Do PlaceNetLabel(i);
Finally
  SchDoc.UnLockViewUpdate;
  SchDoc.GraphicallyInvalidate;
End;

Iter := SchDoc.SchIterator_Create;
Iter.AddFilter_ObjectSet(MkSet(ePort, eNetLabel, ePowerObject));
Obj := Iter.FirstSchObject;
While Obj <> Nil Do Begin
  Case Obj.ObjectId Of
    ePort        : Report.Add('Port ' + Obj.Name);
    eNetLabel    : Report.Add('Label ' + Obj.Text);
    ePowerObject : Report.Add('Power ' + Obj.Text);
  End;
  Obj := Iter.NextSchObject;
End;
SchDoc.SchIterator_Destroy(Iter);

PO := SchServer.SchObjectFactory(ePowerObject, eCreate_Default);
PO.Text := 'GND';
PO.Style := ePowerObjectStyle_PowerGround;
PO.Orientation := eRotate270;
PO.Location := Point(MilsToCoord(1500), MilsToCoord(900));
SchDoc.RegisterSchObjectInContainer(PO);

SE := SchServer.SchObjectFactory(eSheetEntry, eCreate_Default);
SE.Name := 'VIN';
SE.IOType := ePortIOInput;
SE.Side := eLeftSide;
SE.DistanceFromTop := 1;   // grid units from the top edge
SS.AddSchObject(SE);

PI := Cmp.SchIterator_Create;
PI.AddFilter_ObjectSet(MkSet(eParameter));
P := PI.FirstSchObject;
While P <> Nil Do Begin
  If P.Name = 'Manufacturer' Then P.Text := 'Texas Instruments';
  P := PI.NextSchObject;
End;
Cmp.SchIterator_Destroy(PI);

Sym := SchServer.SchObjectFactory(eSchComponent, eCreate_Default);
Sym.LibReference := 'TP';
Sym.Designator.Text := 'TP?';
Pin := SchServer.SchObjectFactory(ePin, eCreate_Default);
Pin.Designator := '1'; Pin.Name := 'TP'; Pin.Electrical := eElectricPassive; Pin.PinLength := MilsToCoord(200);
Sym.AddSchObject(Pin);
Lib.AddSchComponent(Sym);
Lib.GraphicallyInvalidate;

Prj := GetWorkspace.DM_FocusedProject;
If Not Prj.DM_Compile Then Begin ShowError('Compile failed'); Exit; End;
For i := 0 To Prj.DM_ViolationCount - 1 Do
  Report.Add(Prj.DM_Violations(i).DM_ErrorKindString + ': ' + Prj.DM_Violations(i).DM_LongDescriptorString);

OutDir := Prj.DM_GetOutputPath;
If OutDir = '' Then OutDir := ExtractFilePath(Prj.DM_ProjectFullPath) + 'Project Outputs for ' + ChangeFileExt(Prj.DM_ProjectFileName, '');
ForceDirectories(OutDir);

Pcb := Prj.DM_PrimaryImplementationDocument;
If Pcb <> Nil Then ShowMessage('PCB: ' + Pcb.DM_FullPath);
For i := 0 To Prj.DM_PhysicalDocumentCount - 1 Do
  Report.Add(Prj.DM_PhysicalDocuments(i).DM_FullPath + ' room=' + Prj.DM_PhysicalDocuments(i).DM_PhysicalRoomName);

Prj.DM_AddSourceDocument(ExtractFilePath(Prj.DM_ProjectFullPath) + 'Board.OutJob');
ResetParameters;
AddStringParameter('ObjectKind', 'Project');
RunProcess('WorkspaceManager:SaveObject');

For v := 0 To Prj.DM_ProjectVariantCount - 1 Do Begin
  Variant := Prj.DM_ProjectVariants(v);
  Report.Add(Variant.DM_Description + ': ' + IntToStr(Variant.DM_VariationCount) + ' variations');
End;

For i := 0 To Prj.DM_LogicalDocumentCount - 1 Do Begin
  Doc := Prj.DM_LogicalDocuments(i);
  Report.Add(Doc.DM_DocumentKind + ' : ' + Doc.DM_FullPath);
End;

Prj.DM_Compile;
Flat := Prj.DM_DocumentFlattened;
For n := 0 To Flat.DM_NetCount - 1 Do Begin
  Net := Flat.DM_Nets(n);
  Line := Net.DM_NetName + ':';
  For p := 0 To Net.DM_PinCount - 1 Do
    Line := Line + ' ' + Net.DM_Pins(p).DM_PhysicalPartDesignator + '-' + Net.DM_Pins(p).DM_PinNumber;
  Report.Add(Line);
End;

For c := 0 To Flat.DM_ComponentCount - 1 Do Begin
  Cmp := Flat.DM_Components(c);
  Report.Add(Cmp.DM_PhysicalDesignator + ',' + Cmp.DM_Comment + ',' + Cmp.DM_FootPrint + ',' + Cmp.DM_Description);
End;

Procedure Walk(Doc : IDocument; Level : Integer);
Var k : Integer;
Begin
  Report.Add(StringOfChar(' ', Level * 2) + Doc.DM_FileName + ' [' + Doc.DM_PhysicalRoomName + ']');
  For k := 0 To Doc.DM_ChildDocumentCount - 1 Do Walk(Doc.DM_ChildDocuments(k), Level + 1);
End;

